import {Quaternion,Vector3,Euler} from 'three';
import {AnimationIK,animationIKDefaults,validAnimationIK} from './animation-ik.js';

// Shared-pose CCD with optional root translation and independent orientation goals.
export class FullBodyIK{
  constructor(owner,node,slot){
    if(!validAnimationIK('fullBodyIK',node.properties))throw Error('다중 목표 IK 설정 오류');
    this.owner=owner;this.node=node;this.p=node.properties;this.override={};this.effectors=new Map();this.rotation=new Quaternion();this.blendRotation=new Quaternion();this.initial=new Map();this.active=[];this.delta=new Vector3();this.total=new Vector3();this.point=new Vector3();this.startRoot=new Vector3();this.euler=new Euler();this.parentQ=new Quaternion();this.worldQ=new Quaternion();
    const excluded=new Set(this.p.excludedBones),settings=new Map((this.p.boneSettings||[]).map(v=>[v.bone,v]));this.chains=this.p.effectors.map(e=>{
      const tip=owner.group?.getObjectByName(e.bone),names=new Set();let bone=tip;while(bone){names.add(bone.name);if(bone.name===this.p.root)break;bone=bone.parent;}
      const properties={...animationIKDefaults('ccdIK'),root:this.p.root,tip:e.bone,iterations:1,precision:this.p.precision,debug:this.p.debug,enableRotationLimit:true,jointLimits:this.p.jointLimits.filter(l=>names.has(l.bone)&&!excluded.has(l.bone)),target:e.target,targetActor:e.targetActor,space:e.space,positionWeight:e.weight};
      const solver=new AnimationIK(owner,{...node,id:node.id+'/'+e.id,type:'ccdIK',properties},slot);solver.rotationStiffness=new Float64Array(solver.bones.length);solver.bones.forEach((b,i)=>{if(excluded.has(b.name))solver.rotationLimits[i]=0;solver.rotationStiffness[i]=settings.get(b.name)?.rotationStiffness||0;});
      this.effectors.set(e.id,{settings:e,override:{},solver});return solver;
    });
    this.rows=[...this.effectors.values()];this.boneSettings=[];const bones=new Map();for(const s of this.chains)for(const bone of s.bones){bones.set(bone.name,bone);for(const field of ['position','quaternion']){const index=owner.slotKeys.get(bone.uuid+'|'+field+'|');if(!this.initial.has(index))this.initial.set(index,{value:new Float64Array(field==='quaternion'?4:3),field});}}
    for(const p of this.p.boneSettings||[]){const bone=bones.get(p.bone);if(!bone)throw Error('IK 설정 뼈가 체인에 없어요: '+p.bone);this.boneSettings.push({p,bone,index:owner.slotKeys.get(bone.uuid+'|quaternion|')});}
    this.excluded=excluded;this.root=this.chains[0].bones[0];this.rootPosition=owner.slotKeys.get(this.root.uuid+'|position|');this.rootRotation=owner.slotKeys.get(this.root.uuid+'|quaternion|');this.rootStiffness=settings.get(this.root.name)?.positionStiffness||0;this.rootRotationStiffness=settings.get(this.root.name)?.rotationStiffness||0;
    this.jointLimits={set:value=>{const chains=this.chains.filter(s=>s.bones.some(b=>b.name===value.bone));if(!chains.length)throw Error('IK 관절이 없어요.');for(const s of chains)s.jointLimits.set(value);},clear:bone=>{for(const s of this.chains)s.jointLimits.clear(bone);}};
    this.debug={node:node.id,name:node.name,type:'fullBodyIK',tip:[0,0,0],error:0,weight:0,iterations:0,draw:this.p.debug,missingActor:'',rootMotion:[0,0,0],effectors:this.p.effectors.map(e=>({id:e.id,bone:e.bone,tip:[0,0,0],target:[0,0,0],error:0,rotationError:0,weight:e.weight,rotationWeight:e.rotationWeight||0,missingActor:''}))};
  }
  setEffector(id,field,value){const row=this.effectors.get(id);if(!row)throw Error('IK 목표 ID가 없어요.');const next={...row.settings,...row.override,[field]:value};if(!['target','targetActor','weight','rotation','rotationWeight'].includes(field)||!validAnimationIK('fullBodyIK',{...this.p,effectors:[next]}))throw Error('IK 목표 값 범위를 확인하세요.');row.override[field]=Array.isArray(value)?[...value]:value;}
  setRoot(mode,pull,maxDistance){const next={...this.p,rootBehavior:mode,rootPull:pull,rootMaxDistance:maxDistance};if(!validAnimationIK('fullBodyIK',next))throw Error('IK 루트 설정 범위를 확인하세요.');Object.assign(this.override,{rootBehavior:mode,rootPull:pull,rootMaxDistance:maxDistance});}
  write(s,pose){for(let i=0;i<s.bones.length;i++)s.chain[i].quaternion.toArray(pose[this.owner.slotKeys.get(s.bones[i].uuid+'|quaternion|')]);}
  moveRoot(pose,pull,maxDistance){
    if(!this.active.length||!pull||this.excluded.has(this.root.name)||this.rootStiffness===1)return;this.delta.set(0,0,0);for(const s of this.active){s.readPose(pose);s.chain.at(-1).getWorldPosition(this.point);this.delta.add(s.target).sub(this.point);}this.delta.multiplyScalar(pull*(1-this.rootStiffness)/this.active.length);const first=this.active[0];first.readPose(pose);first.chain[0].getWorldPosition(this.point);this.total.copy(this.point).add(this.delta).sub(this.startRoot).clampLength(0,maxDistance);this.point.copy(this.startRoot).add(this.total);first.chain[0].parent.worldToLocal(this.point);this.point.toArray(pose[this.rootPosition]);
  }
  orient(row,pose){const s=row.solver,weight=row.override.rotationWeight??row.settings.rotationWeight??0;if(!weight||s.debug.missingActor||this.excluded.has(row.settings.bone)||s.rotationStiffness.at(-1)===1)return;s.readPose(pose);const tip=s.chain.at(-1);this.worldQ.copy(s.tipRotation).slerp(s.targetRotation,weight);tip.parent.getWorldQuaternion(this.parentQ);tip.quaternion.copy(this.parentQ.invert().multiply(this.worldQ));const last=s.chain.length-1;if(s.rotationStiffness[last])tip.quaternion.slerp(this.rotation.fromArray(this.initial.get(this.owner.slotKeys.get(s.bones[last].uuid+'|quaternion|')).value),s.rotationStiffness[last]);s.limitRotation(last);tip.quaternion.toArray(pose[this.owner.slotKeys.get(s.bones[last].uuid+'|quaternion|')]);}
  apply(pose,weight){
    const p={...this.p,...this.override},mode=p.rootBehavior||'fixed';this.debug.weight=weight;this.debug.iterations=0;this.debug.missingActor='';for(const [index,row] of this.initial)row.value.set(pose[index]);
    if(weight>0)for(const {p,bone,index} of this.boneSettings)if(p.preferredAngle&&!(mode==='pin'&&bone===this.root)&&!this.excluded.has(bone.name)&&(p.rotationStiffness||0)<1){this.rotation.fromArray(pose[index]);this.blendRotation.setFromEuler(this.euler.set(...p.preferredAngle.map(v=>v*Math.PI/180)));this.rotation.multiply(this.blendRotation).toArray(pose[index]);}
    const active=this.active;active.length=0;for(const [i,row] of this.rows.entries()){
      const s=row.solver,e={...row.settings,...row.override},d=this.debug.effectors[i];s.override={target:e.target,targetActor:e.targetActor,rotation:e.rotation||[0,0,0]};s.p.positionWeight=e.weight;s.readPose(pose);s.rotationStiffness[0]=mode==='pin'?1:this.rootRotationStiffness;const available=s.targets();d.weight=e.weight;d.rotationWeight=e.rotationWeight||0;d.missingActor=s.debug.missingActor;s.target.toArray(d.target);if(d.missingActor)this.debug.missingActor=d.missingActor;if(available&&e.weight>0)active.push(s);
    }
    this.chains[0].readPose(pose);this.chains[0].chain[0].getWorldPosition(this.startRoot);if(weight>0&&mode==='prePull')this.moveRoot(pose,p.rootPull??1,p.rootMaxDistance??100000);
    if(weight>0)for(let iteration=0;iteration<p.iterations;iteration++){
      for(let index=0;index<active.length;index++){const s=active[iteration%2?active.length-1-index:index];s.readPose(pose);s.ccd();this.write(s,pose);}for(const row of this.rows)this.orient(row,pose);if(mode==='free')this.moveRoot(pose,p.rootPull??1,p.rootMaxDistance??100000);
      this.debug.iterations=iteration+1;let error=0;for(const s of active){s.readPose(pose);s.chain.at(-1).getWorldPosition(s.origin);error=Math.max(error,s.origin.distanceTo(s.target));}if(error<=p.precision)break;
    }
    if(weight<1)for(const [index,{value,field}] of this.initial){if(field==='quaternion')this.rotation.fromArray(value).slerp(this.blendRotation.fromArray(pose[index]),weight).toArray(pose[index]);else for(let k=0;k<3;k++)pose[index][k]=value[k]+(pose[index][k]-value[k])*weight;}
    this.debug.error=0;for(const [i,s] of this.chains.entries()){s.readPose(pose);s.chain.at(-1).getWorldPosition(s.origin);const d=this.debug.effectors[i];s.origin.toArray(d.tip);d.error=d.missingActor?0:s.origin.distanceTo(s.target);s.chain.at(-1).getWorldQuaternion(this.worldQ);d.rotationError=d.missingActor?0:this.worldQ.angleTo(s.targetRotation);if(d.weight>0)this.debug.error=Math.max(this.debug.error,d.error);s.debug.tip=d.tip;s.debug.weight=weight;s.debug.error=d.error;s.drawDebug();}this.chains[0].chain[0].getWorldPosition(this.point);this.point.sub(this.startRoot).toArray(this.debug.rootMotion);for(let i=0;i<3;i++)this.debug.tip[i]=this.debug.effectors[0].tip[i];return this.debug;
  }
  dispose(){for(const s of this.chains)s.dispose();this.chains.length=0;this.effectors.clear();this.rows.length=0;this.active.length=0;this.initial.clear();}
}
